mappings.PAY.response:
status = 200
  ? (body.status = "SUCCESS" and $type(body.gpRef) = "string" and body.gpRef != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.gpRef, "code": body.code}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 400) and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: status = 400
  ? {"outcome": "FAILED", "code": "HTTP_400", "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.INQUIRY.response:
status = 200
  ? (body.status = "DUE" and $type(body.billRef) = "string" and $type(body.outstanding) = "string" and $type(body.minimum) = "string"
      ? {"outcome": "SUCCESS", "partnerRef": body.billRef, "code": body.code, "attributes": {"outstanding": body.outstanding, "minimum": body.minimum}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 422 and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.status = "SUCCESS" and $type(body.gpRef) = "string" and body.gpRef != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.gpRef, "code": body.code}
      : body.status = "FAILED" and $type(body.code) = "string" and body.code != ""
        ? {"outcome": "FAILED", "code": body.code, "message": body.message}
        : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.status = "REVERSED" and $type(body.gpRef) = "string" and body.gpRef != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.gpRef, "code": body.code}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 404 or status = 422) and $type(body.code) = "string" and body.code != ""
  ? {"outcome": "FAILED", "code": body.code, "message": body.message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}
